171→function Step4({ motherBreed, calves, onUpdate }: { motherBreed: string; calves: CalfData[]; onUpdate: (calves: CalfData[]) => void }) {
172→    const today = new Date().toISOString().split('T')[0];
173→    const updateCalf = (index: number, field: keyof CalfData, value: string) => {
174→        const updated = [...calves];
175→        updated[index] = { ...updated[index], [field]: value };
176→        onUpdate(updated);
177→    };
178→    const addCalf = () => {
179→        onUpdate([...calves, { sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
180→    };
181→    const removeCalf = (index: number) => {
182→        if (calves.length > 1) onUpdate(calves.filter((_, i) => i !== index));
183→    };
184→
185→    return (
186→        <div className="flex flex-col gap-4">
187→            <h2 className="text-2xl font-bold">Datos de la cría</h2>
188→            {calves.map((calf, i) => {
189→                const daysAgo = Math.floor((Date.now() - new Date(calf.birth_date).getTime()) / (1000 * 60 * 60 * 24));
190→                return (
191→                    <div key={i} className="flex flex-col gap-3 border-2 border-black p-4">
192→                        <div className="flex items-center justify-between">
193→                            <span className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Cría {calves.length > 1 ? i + 1 : ''}</span>
194→                            {calves.length > 1 && (
195→                                <button onClick={() => removeCalf(i)} className="text-xs text-[#E53935]">Eliminar</button>
196→                            )}
197→                        </div>
198→                        <div>
199→                            <label className="text-xs font-semibold text-[#757575]">Fecha de nacimiento</label>
200→                            <input type="date" value={calf.birth_date} onChange={(e) => updateCalf(i, 'birth_date', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-sm" />
201→                            {daysAgo > 7 && <p className="mt-1 text-xs font-medium text-[#E65100]">Supera el plazo legal de 7 días. Se recomienda registrarlo cuanto antes.</p>}
202→                        </div>
203→                        <div>
204→                            <label className="text-xs font-semibold text-[#757575]">Sexo</label>
205→                            <div className="mt-1 flex gap-0">
206→                                {(['female', 'male'] as const).map((s) => (
207→                                    <button key={s} onClick={() => updateCalf(i, 'sex', s)} className={`flex-1 border-2 border-black py-2 text-xs font-bold ${calf.sex === s ? 'bg-black text-white' : ''}`}>
208→                                        {s === 'female' ? 'Hembra' : 'Macho'}
209→                                    </button>
210→                                ))}
211→                            </div>
212→                        </div>
213→                        <div>
214→                            <label className="text-xs font-semibold text-[#757575]">Raza</label>
215→                            <input type="text" value={calf.breed} onChange={(e) => updateCalf(i, 'breed', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-sm" />
216→                        </div>
217→                        <div>
218→                            <label className="text-xs font-semibold text-[#757575]">Nombre (opcional)</label>
219→                            <input type="text" value={calf.name} onChange={(e) => updateCalf(i, 'name', e.target.value)} className="mt-1 h-[44px] w-full bg-[#F5F5F5] px-3 text-sm" placeholder="Ej: Txuri" />
220→                        </div>
221→                    </div>
222→                );
