231→function Step5({ sub, mother, father, calves, animals }: { sub: SubExploitation; mother: number; father: number | null; calves: CalfData[]; animals: Animal[] }) {
232→    const motherAnimal = animals.find((a) => a.id === mother);
233→    const fatherAnimal = father ? animals.find((a) => a.id === father) : null;
234→
235→    return (
236→        <div className="flex flex-col gap-4">
237→            <h2 className="text-2xl font-bold">Resumen</h2>
238→            <div className="flex flex-col gap-3 border-2 border-black p-4">
239→                <div>
240→                    <p className="text-xs text-[#757575]">Subexplotación</p>
241→                    <p className="text-sm font-bold">{speciesLabels[sub.species]} · {sub.exploitation_type}</p>
242→                </div>
243→                <div>
244→                    <p className="text-xs text-[#757575]">Madre</p>
245→                    <p className="text-sm font-bold">{motherAnimal?.crotal_code} {motherAnimal?.name ? `(${motherAnimal.name})` : ''}</p>
246→                </div>
247→                {fatherAnimal && (
248→                    <div>
249→                        <p className="text-xs text-[#757575]">Padre</p>
250→                        <p className="text-sm font-bold">{fatherAnimal.crotal_code} {fatherAnimal.name ? `(${fatherAnimal.name})` : ''}</p>
