import { Head, router, usePage } from '@inertiajs/react';
import { Baby, Check, CheckCircle, ChevronLeft, ChevronRight, Camera, Pencil, AlertTriangle } from 'lucide-react';
import { useEffect, useState } from 'react';
import AppLayout from '@/layouts/app-layout';
import type { BreadcrumbItem } from '@/types';

interface Animal {
    id: number;
    crotal_code: string;
    breed: string;
    sex: string;
    name: string | null;
    birth_date: string;
}

interface SubExploitation {
    id: number;
    species: string;
    exploitation_type: string;
    current_capacity: number;
    max_capacity: number;
    status: string;
    animals: Animal[];
}

interface Exploitation {
    id: number;
    name: string;
    rega_code: string;
    sub_exploitations: SubExploitation[];
}

interface Props {
    exploitation: Exploitation;
}

interface CalfData {
    sex: string;
    breed: string;
    name: string;
    birth_date: string;
}

const breadcrumbs: BreadcrumbItem[] = [
    { title: 'Mi Explotación', href: '/dashboard' },
    { title: 'Comunicar Nacimiento', href: '/nacimientos/crear' },
];

const STEPS = [
    'Subexplotación',
    'Madre',
    'Padre',
    'Datos cría',
    'Resumen',
    'Confirmación',
];

const speciesLabels: Record<string, string> = {
    bovine: 'Bovino',
    ovine: 'Ovino',
    caprine: 'Caprino',
    equine: 'Equino',
};

function ProgressBar({ currentStep }: { currentStep: number }) {
    return (
        <div className="flex gap-1">
            {STEPS.map((_, i) => (
                <div key={i} className={`h-1 flex-1 ${i <= currentStep ? 'bg-[#E53935]' : 'bg-[#E0E0E0]'}`} />
            ))}
